import{_ as n,o as r,c as s,a3 as e,j as t}from"./chunks/framework.BcGtP7Ct.js";const o="/paper-reading/assets/image-20261016-124117.CNcEPF8V.png",p="/paper-reading/assets/image-20261016-124408.DTtb0fqf.png",T=JSON.parse('{"title":"GPT-1 (2019) · 笔记区","description":"","frontmatter":{"title":"GPT-1 (2019) · 笔记区","aside":false,"pageClass":"wide","editLink":false},"headers":[],"relativePath":"paper-notes/GPT1.md","filePath":"papers/paper-notes/GPT1.md"}'),l={name:"paper-notes/GPT1.md"};function i(h,a,c,g,u,P){return r(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="gpt-1-2018-·-笔记区" tabindex="-1">GPT-1 (2018) · 笔记区 <a class="header-anchor" href="#gpt-1-2018-·-笔记区" aria-label="Permalink to &quot;GPT-1 (2018) · 笔记区&quot;">​</a></h1><h1 id="gpt-gpt-2-gpt-3-总结" tabindex="-1"><a href="https://www.cnblogs.com/xumaomao/p/17926963.html" title="发布于 2023-12-25 20:54" target="_blank" rel="noreferrer">GPT / GPT-2 / GPT-3 总结</a> <a class="header-anchor" href="#gpt-gpt-2-gpt-3-总结" aria-label="Permalink to &quot;[GPT / GPT-2 / GPT-3 总结](https://www.cnblogs.com/xumaomao/p/17926963.html &quot;发布于 2023-12-25 20:54&quot;)&quot;">​</a></h1><p>论文：<a href="https://link.zhihu.com/?target=https%3A//cdn.openai.com/research-covers/language-unsupervised/language_understanding_paper.pdf" target="_blank" rel="noreferrer">GPT: Improving Language Understanding by Generative Pre-Training</a></p><p><strong><a href="https://www.cnblogs.com/xumaomao/p/17926963.html" target="_blank" rel="noreferrer">GPT-1 采用了两阶段训练的方式</a>：</strong></p><p><strong>1. 第一阶段 pre-training，在海量文本上训练，无需label，根据前k-1个词预测第k个单词是什么，第一阶段的训练让模型拥有了很多的先验知识，模型具有非常强的泛化性</strong></p><p><strong>2. 第二阶段在特定任务上supervised fine-tuning ，让模型能适应不同的任务，提高模型在特定任务上的准确性</strong></p><p><strong>supervised fine-tuning 就是在有label的数据集上微调，具体来说就是替换掉第一阶段的最后一层，在监督数据集上训练</strong></p><p><img src="'+o+'" alt=""><img src="'+p+'" alt=""></p><h2 id="gpt1总结" tabindex="-1">GPT1总结 <a class="header-anchor" href="#gpt1总结" aria-label="Permalink to &quot;GPT1总结&quot;">​</a></h2><p>1. 它是最早一批提出在 NLP 任务上使用 pre-train + fine-tuning 范式的工作。</p><p>2. GPT 的实验证明了模型的精度和泛化能力会随着解码器层数增加而不断提升，而且目前还有提升空间</p><p>3. 预训练模型具有 zero-shot 的能力，并且能随着预训练的进行不断增强</p><h1 id="gpt2" tabindex="-1">GPT2 <a class="header-anchor" href="#gpt2" aria-label="Permalink to &quot;GPT2&quot;">​</a></h1><p>论文：<a href="https://link.zhihu.com/?target=https%3A//cdn.openai.com/better-language-models/language_models_are_unsupervised_multitask_learners.pdf" target="_blank" rel="noreferrer">GPT-2: Language Models are Unsupervised Multitask Learners</a></p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>GPT1采用了<strong>pre-train + fine-tuning</strong>训练方式，也就是说为了适应不同的训练任务，模型还是需要在特定任务的数据集上<strong>微调</strong>，仍然存在较多人工干预的成本。GPT-2 想彻底解决这个问题，通过 zero-shot，在迁移到其他任务上的时候不需要额外的标注数据，也不需要额外的模型训练。</p><h2 id="训练数据改造" tabindex="-1">训练数据改造 <a class="header-anchor" href="#训练数据改造" aria-label="Permalink to &quot;训练数据改造&quot;">​</a></h2><p>在 GPT-1 中，下游任务需要对不同任务的输入序列进行改造，在序列中加入了开始符、分隔符和结束符之类的特殊标识符，但是在 zero-shot 前提下，我们无法根据不同的下游任务去添加这些标识符，因为不进行额外的微调训练，模型在预测的时候根本不认识这些特殊标记。所以在 zero-shot 的设定下，不同任务的输入序列应该与训练时见到的文本长得一样，也就是以<strong>自然语言</strong>的形式去作为输入，例如下面两个任务的输入序列是这样改造的：</p>',18),t("blockquote",null,[t("p",{answer:""},"机器翻译任务：translate to french, { english text }, { french text } 阅读理解任务：answer the question, { document }, { question },")],-1),e('<p>GPT-2 的核心思想就是，当模型的容量非常大且数据量足够丰富时，仅仅靠语言模型的学习便可以完成其他有监督学习的任务，不需要在下游任务微调。</p><h2 id="模型结构" tabindex="-1">模型结构 <a class="header-anchor" href="#模型结构" aria-label="Permalink to &quot;模型结构&quot;">​</a></h2><p>在模型结构方面，整个 GPT-2 的模型框架与 GPT-1 相同，只是做了几个地方的调整，这些调整更多的是被当作训练时的 trick，而不作为 GPT-2 的创新，具体为以下几点：</p><p>1. 后置层归一化（ post-norm ）改为前置层归一化（ pre-norm ）;</p><p>2. 在模型最后一个自注意力层之后，额外增加一个层归一化;</p><p>3. 调整参数的初始化方式，按残差层个数进行缩放，缩放比例为 1 : √n;</p><p>4. 输入序列的最大长度从 512 扩充到 1024;</p><p>GPT-2 进行上述模型调整的主要原因在于，随着模型层数不断增加，梯度消失和梯度爆炸的风险越来越大，这些调整能够减少预训练过程中各层之间的方差变化，使梯度更加稳定</p><h2 id="gpt2总结" tabindex="-1">GPT2总结 <a class="header-anchor" href="#gpt2总结" aria-label="Permalink to &quot;GPT2总结&quot;">​</a></h2><p>整体来看，GPT-2 相比于 GPT-1 有如下几点区别：</p><p>1. 主推 zero-shot，而 GPT-1 为 pre-train + fine-tuning； 2. 训练数据规模更大，GPT-2 为 800w 文档 40G，GPT-1 为 5GB； 3. 模型大小，GPT-2 最大 15 亿参数，GPT-1为 1 亿参数； 4. 模型结构调整，层归一化和参数初始化方式； 5. 训练参数，batch_size 从 64 增加到 512，上文窗口大小从 512 增加到 1024，等等；</p><h1 id="gpt3" tabindex="-1">GPT3 <a class="header-anchor" href="#gpt3" aria-label="Permalink to &quot;GPT3&quot;">​</a></h1><p>论文：<a href="https://link.zhihu.com/?target=https%3A//arxiv.org/pdf/2005.14165.pdf" target="_blank" rel="noreferrer">GPT-3: Language Models are Few-Shot Learners</a></p><h2 id="背景-1" tabindex="-1">背景 <a class="header-anchor" href="#背景-1" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>虽然 GPT-2 主推的 zero-shot 在创新度上有比较高的水平，但是由于其在效果上表现平平，所以在业界并没有取得比较大的影响力，而 GPT-3 正是为了解决效果上的问题而提出的。GPT-3 不再去追求那种极致的不需要任何样本就可以表现很好的模型，而是考虑像人类的学习方式那样，仅仅使用极少数样本就可以掌握某一个任务。</p><h2 id="模型结构-1" tabindex="-1">模型结构 <a class="header-anchor" href="#模型结构-1" aria-label="Permalink to &quot;模型结构&quot;">​</a></h2><p>在模型结构上，GPT-3 延续使用 GPT 模型结构，但是引入了 Sparse Transformer 中的 sparse attention 模块（稀疏注意力）。</p><p>sparse attention 与传统 self-attention（称为 dense attention） 的区别在于：</p><blockquote><p>dense attention：每个 token 之间两两计算 attention，复杂度 O(n²) sparse attention：每个 token 只与其他 token 的一个子集计算 attention，复杂度 O(n*logn)</p></blockquote><p>具体来说，sparse attention 除了相对距离不超过 k 以及相对距离为 k，2k，3k，... 的 token，其他所有 token 的注意力都设为 0，如下图所示：</p><p><img src="https://img2024.cnblogs.com/blog/1704997/202504/1704997-20250417115648657-794611568.png" alt=""></p><p>使用 sparse attention 的好处主要有以下两点：</p><p>1. 减少注意力层的计算复杂度，节约显存和耗时，从而能够处理更长的输入序列；</p><p>2. 具有&quot;局部紧密相关和远程稀疏相关&quot;的特性，对于距离较近的上下文关注更多，对于距离较远的上下文关注较少</p><h2 id="下游任务评估方法" tabindex="-1">下游任务评估方法 <a class="header-anchor" href="#下游任务评估方法" aria-label="Permalink to &quot;下游任务评估方法&quot;">​</a></h2><p>GPT-3 在下游任务的评估与预测时，提供了三种不同的方法：</p><blockquote><p>Zero-shot：仅使用当前任务的自然语言描述，不进行任何梯度更新； One-shot：当前任务的自然语言描述，加上一个简单的输入输出样例，不进行任何梯度更新； Few-shot：当前任务的自然语言描述，加上几个简单的输入输出样例，不进行任何梯度更新；</p></blockquote><p>其中 Few-shot 也被称为 in-context learning，虽然它与 fine-tuning 一样都需要一些有监督标注数据，但是两者的区别是：</p><p>1. 【本质区别】fine-tuning 基于标注数据对模型参数进行更新，而 in-context learning 使用标注数据时不做任何的梯度回传，模型参数不更新；</p><p>2. in-context learning 依赖的数据量（10～100）远远小于 fine-tuning 一般的数据量；</p><p>最终通过大量下游任务实验验证，Few-shot 效果最佳，One-shot 效果次之，Zero-shot 效果最差</p><h2 id="gpt3总结" tabindex="-1">GPT3总结 <a class="header-anchor" href="#gpt3总结" aria-label="Permalink to &quot;GPT3总结&quot;">​</a></h2><p>整体来看，GPT-3 相比于 GPT-2 有如下几点区别：</p><blockquote><p>1. 效果上，超出 GPT-2 非常多，能生成人类难以区分的新闻文章； 2. 主推 few-shot，相比于 GPT-2 的 zero-shot，具有很强的创新性； 3. 模型结构略微变化，采用 sparse attention 模块； 4. 海量训练语料 45TB（清洗后 570GB），相比于 GPT-2 的 40GB； 5. 海量模型参数，最大模型为 1750 亿，GPT-2 最大为 15 亿参数；</p></blockquote><p>GPT3还存在一些局限性： 1. 当生成文本长度较长时，GPT-3 还是会出现各种问题，比如重复生成一段话，前后矛盾，逻辑衔接不好等等； 2. 模型最终呈现的效果取决于训练数据，这会导致模型会出现各种各样的&quot;偏见&quot;</p><h2 id="few-shot-相比于-zero-shot-为什么更有效" tabindex="-1">few-shot 相比于 zero-shot 为什么更有效？ <a class="header-anchor" href="#few-shot-相比于-zero-shot-为什么更有效" aria-label="Permalink to &quot;few-shot 相比于 zero-shot 为什么更有效？&quot;">​</a></h2><p>在few-shot给的几个样例在新任务时会作为条件输入，相当于模型拥有了该任务更多的先验知识</p><h1 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h1><a class="link-card" href="https://zhuanlan.zhihu.com/p/609716668" target="_blank" rel="noopener"><span class="lc-icon">🔗</span><span class="lc-body"><span class="lc-title">GPT / GPT-2 / GPT-3 / InstructGPT 进化之路</span><span class="lc-url">zhuanlan.zhihu.com</span></span><span class="lc-arrow">↗</span></a><a class="link-card" href="https://xiaomage666.feishu.cn/wiki/GI85wfUaBiUUPtkVpeic66EWnsc?table=blkg3mNDFPfrcEPJ" target="_blank" rel="noopener"><span class="lc-icon">🔗</span><span class="lc-body"><span class="lc-title">预训练语言模型之 GPT-1，GPT-2，GPT-3</span><span class="lc-url">xiaomage666.feishu.cn</span></span><span class="lc-arrow">↗</span></a><a class="link-card" href="https://www.cnblogs.com/xuxixi-blog/p/17235740.html" target="_blank" rel="noopener"><span class="lc-icon">🔗</span><span class="lc-body"><span class="lc-title">GPT系列算法</span><span class="lc-url">cnblogs.com</span></span><span class="lc-arrow">↗</span></a>',41)])])}const G=n(l,[["render",i]]);export{T as __pageData,G as default};
